package sk.knizat.tennisclub.controller;

import jakarta.validation.ConstraintViolation;
import jakarta.validation.ConstraintViolationException;
import jakarta.validation.Path;
import org.junit.jupiter.api.Test;
import org.springframework.http.ProblemDetail;
import org.springframework.validation.BeanPropertyBindingResult;
import org.springframework.validation.FieldError;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.MissingServletRequestParameterException;

import java.util.Map;
import java.util.Set;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/** Covers handler branches that the controller slice test cannot reach. */
class GlobalExceptionHandlerTest {

    private final GlobalExceptionHandler handler = new GlobalExceptionHandler();

    @Test
    void should_mapViolationsToErrors_when_constraintViolation() {
        Path path = mock(Path.class);
        when(path.toString()).thenReturn("findById.id");
        @SuppressWarnings("unchecked")
        ConstraintViolation<Object> violation = mock(ConstraintViolation.class);
        when(violation.getPropertyPath()).thenReturn(path);
        when(violation.getMessage()).thenReturn("must be positive");

        ProblemDetail problem = handler.handleConstraintViolation(new ConstraintViolationException(Set.of(violation)));

        assertThat(problem.getStatus()).isEqualTo(400);
        assertThat(problem.getTitle()).isEqualTo("Validation failed");
        assertThat(problem.getProperties()).containsEntry("errors", Map.of("findById.id", "must be positive"));
    }

    @Test
    void should_nameParameter_when_missingRequestParameter() {
        ProblemDetail problem = handler.handleMissingParameter(
                new MissingServletRequestParameterException("from", "Instant"));

        assertThat(problem.getStatus()).isEqualTo(400);
        assertThat(problem.getTitle()).isEqualTo("Missing parameter");
        assertThat(problem.getDetail()).isEqualTo("Required parameter 'from' is missing");
    }

    @Test
    void should_useFallbackMessage_when_fieldErrorHasNoDefaultMessage() throws Exception {
        BeanPropertyBindingResult binding = new BeanPropertyBindingResult(new Object(), "request");
        binding.addError(new FieldError("request", "name", null));
        binding.addError(new FieldError("request", "name", "second error is ignored"));
        var parameter = new org.springframework.core.MethodParameter(
                GlobalExceptionHandlerTest.class.getDeclaredMethod("sample", String.class), 0);

        ProblemDetail problem = handler.handleMethodArgumentNotValid(
                new MethodArgumentNotValidException(parameter, binding));

        assertThat(problem.getProperties()).containsEntry("errors", Map.of("name", "invalid value"));
    }

    @SuppressWarnings("unused")
    void sample(String name) {
        // signature only; used to build a MethodParameter
    }
}
